#!/usr/bin/env python3
"""Render frozen v5 measurements; do not merge training and test headlines."""
import csv,json,os,statistics
from pathlib import Path
os.environ.setdefault('MPLCONFIGDIR','/tmp/lineage-mpl')
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
from collections import Counter
ROOT=Path(__file__).resolve().parents[2];HERE=Path(__file__).parent
r=json.loads((HERE/'results/report.json').read_text());assert len(r['sheets'])==28,'Incomplete paired evaluation'
sets={'new-projects':[s for s in r['sheets'] if s['group'] in ('virden','ruttan')],'pahala-unseen-page':[s for s in r['sheets'] if s['group']=='pahala-unseen-page'],'open100-historical':[s for s in r['sheets'] if s['group']=='open100' and s['role']=='historical-regression'],'pahala-training':[s for s in r['sheets'] if s['group']=='pahala-training'],'synthetic-regression':[s for s in r['sheets'] if s['group']=='synthetic-regression']}
def counts(tp,fp,fn):return {'tp':tp,'fp':fp,'fn':fn,'precision':tp/(tp+fp) if tp+fp else 0,'recall':tp/(tp+fn) if tp+fn else 0,'f1':2*tp/(2*tp+fp+fn) if 2*tp+fp+fn else 0}
a={}
for name,ss in sets.items():
 a[name]={}
 for v in ('v4','v5'):
  d={m:counts(**{k:sum(s['variants'][v]['scores'][m][k] for s in ss) for k in ('tp','fp','fn')}) for m in ('localization','connections','oracle_boxes')}
  d['mean_sheet_median_seconds']=statistics.mean(s['variants'][v]['timing']['median'] for s in ss);d['miss_attribution']=dict(sum((Counter(s['variants'][v]['miss_attribution']) for s in ss),Counter()));a[name][v]=d
pct=lambda x:f'{x*100:.2f}%'
pm=lambda d:' / '.join(pct(d[k]) for k in ('precision','recall','f1'))
figures=HERE/'figures';figures.mkdir(exist_ok=True)
groups=['new-projects','pahala-unseen-page','open100-historical','synthetic-regression'];names=['Virden + Ruttan\n4 ROIs / 2 projects','Pahala p21\nunseen page, known project','OPEN100 6–11\nhistorical regression','Synthetic 8\nhistorical regression'];x=np.arange(len(groups))
fig,axes=plt.subplots(1,3,figsize=(17,5),layout='constrained')
for ax,metric,title in zip(axes,['localization','connections',None],['Symbol recall (IoU >= .50)','Connection recall','Mean paired-sheet median latency']):
 for i,v in enumerate(('v4','v5')):
  values=[100*a[g][v][metric]['recall'] if metric else a[g][v]['mean_sheet_median_seconds'] for g in groups];bars=ax.bar(x+(i-.5)*.36,values,.34,color=['#969fa9','#147b73'][i],label=v);ax.bar_label(bars,labels=[f'{n:.2f}'+('%' if metric else 's') for n in values],fontsize=8,padding=3)
 ax.set_xticks(x,names,fontsize=8,rotation=10);ax.set_title(title);ax.spines[['top','right']].set_visible(False);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True);ax.set_ylim(0,max(ax.get_ylim()[1]*1.14,1))
axes[0].legend(frameon=False);fig.suptitle('Frozen v4 → v5 | training and threshold-validation sheets excluded',fontsize=14);fig.savefig(figures/'generalization-speed.png',dpi=170);plt.close(fig)
fig,ax=plt.subplots(figsize=(10,4),layout='constrained');keys=['recovered','missing_symbol','disabled_symbol_port','line_or_port_routing'];labels=['Recovered','Missing endpoint symbol','Weak-circle port constraint','Line / port routing']
for i,v in enumerate(('v4','v5')):
 values=[a['new-projects'][v]['miss_attribution'].get(k,0) for k in keys];bars=ax.barh(np.arange(4)+(i-.5)*.32,values,.3,label=v,color=['#969fa9','#147b73'][i]);ax.bar_label(bars,padding=3)
ax.set_yticks(np.arange(4),labels);ax.invert_yaxis();ax.set_xlim(0,max(5,ax.get_xlim()[1]*1.15));ax.set_title('New projects: 26 annotated edges, priority-based attribution');ax.legend();ax.spines[['top','right']].set_visible(False);fig.savefig(figures/'new-project-misses.png',dpi=170);plt.close(fig)
with (HERE/'per-sheet.csv').open('w',newline='') as f:
 w=csv.writer(f,lineterminator='\n');w.writerow(['group','id','role','variant','symbol_tp','symbol_fp','symbol_fn','connection_tp','connection_fp','connection_fn','connection_precision','connection_recall','connection_f1','median_seconds','min_seconds','max_seconds'])
 for s in r['sheets']:
  for v,d in s['variants'].items():w.writerow([s['group'],s['id'],s['role'],v,*[d['scores']['localization'][k] for k in ('tp','fp','fn')],*[d['scores']['connections'][k] for k in ('tp','fp','fn','precision','recall','f1')],*[d['timing'][k] for k in ('median','min','max')]])
train=json.loads((HERE/'TRAINING.json').read_text());new=a['new-projects'];old,newv=new['v4'],new['v5']
lines=['# v5 학습 기호 검출·새 프로젝트 검증','',f"기준 앱 `{r['baseline']}` → 평가 고정 앱 `aef3ca96f8eb6d65ac7c3405b0be6c5da21ffa8b`. 실행 {r['evaluated_at']}. 문서 커밋은 실행 앱과 별개다.",'',f"학습·문턱값 선정에 쓰지 않은 Virden·Ruttan의 지정 영역 4곳에서 기호 재현율 **{pct(old['localization']['recall'])}→{pct(newv['localization']['recall'])}**, 연결 재현율 **{pct(old['connections']['recall'])}→{pct(newv['connections']['recall'])}**, 연결 F1 **{pct(old['connections']['f1'])}→{pct(newv['connections']['f1'])}**를 측정했다. OCR+추출 지연은 **{old['mean_sheet_median_seconds']:.3f}→{newv['mean_sheet_median_seconds']:.3f}초**다.",'','새 프로젝트 정답은 기호 28개·연결 26개다. 표본이 작고 Ruttan 두 장은 같은 플랜트의 상관된 개정본이다. 단일 작성자가 원본을 보고 영역·정답을 고정했다. 새 프로젝트의 원본 외관을 주석과 일반 전처리 설계에 참고했으므로, 독립된 전문가의 블라인드 검증이라고 표현하지 않는다. 전체 페이지 또는 일반 건축·전자회로 도면의 성능으로 확대 해석할 수 없다.','','## 실제로 학습한 모델','','CPU에서 32×32 HOG 324차원, foreground grid 64차원, 크기·종횡비·외부 선 문맥 7차원을 이용한 OpenCV Random Forest 객체성 검출기를 학습했다. 학습되지 않은 사전 규칙만 추가한 것은 아니지만, YOLO/Transformer 계열 신경망을 미세조정한 것도 아니다. 학습하는 것은 기호 영역과 배경의 구분이며, 국제표준 ID나 설비 종류를 학습했다고 주장하지 않는다.','',f"선정 모델은 128개 트리, 최대 깊이 18, seed 20261028이다. OPEN100 0–3의 실제 도면 4장과 Pāhala 23·24쪽 영역, 합성 12장으로 {sum(s['symbols'] for s in train['training_sheets'])}개 정답 기호에서 **{train['training_samples']:,}개 파생 영역**(양성 {train['positive_samples']:,}, 음성 {train['negative_samples']:,})을 만들었다. {train['training_seconds']:.3f}초 학습했으며 가중치 SHA-256은 `{train['weights_sha256']}`다. 파생 영역 수를 독립 도면 수로 계산하지 않는다.",'','첫 모델 R1과 회전·반전 증강을 포함한 두 번째 모델 R2를 실제로 학습했다. R2는 85,844개 파생 영역, 64개 트리, 561.826초였다. OPEN100 4·5, Pāhala20, 합성4장의 검증 세 출처에 대해 `mean(connection F1 + 0.25 × localization F1)`로 비교해 R1/추가 문턱값 0.8/기존 후보 제거 문턱값 0.3을 골랐다. R2는 선택되지 않았다. 최종 R1의 학습 증강은 정확 영역과 작은 위치·크기 변동이며 회전·반전 학습 결과가 최종 가중치에 포함됐다고 주장하지 않는다. [선정 기록](MODEL-SELECTION.json), [R1 학습 기록](TRAINING.json), [R2 학습 기록](iterations/TRAINING-r2.json)에 근거가 있다.','','## 데이터 역할과 실제 출처','','- **학습**: OPEN100 0–3, Pāhala23·24, PLAN의 새 합성12.','- **문턱값 검증**: OPEN1004·5, Pāhala20, 합성232·238·470·278.','- **새 프로젝트 평가**: [Virden 실제 P&ID](https://www.gov.mb.ca/sd/eal/registries/5697virden/2019-04-26_5697_00_phase_2_p_and_i_drwngs.pdf) 5·7쪽, [Ruttan 기술 제출 문서](https://gov.mb.ca/sd/eal/registries/294.30/20250618_letter.pdf) 50·62쪽. 모두 전체 페이지를 PNG로 입력하고 지정 영역만 채점했다. Virden은 스캔 기반, Ruttan은 옅은 벡터 선과 외곽선 글자 등 서로 다른 표현을 포함한다.','- **알려진 프로젝트의 미학습 페이지**: [Pāhala 개념설계](https://www.epa.gov/system/files/documents/2021-08/pahala-wwtp-design-build-drawings-2021-07-23.pdf) 21쪽. 프로젝트 독립 평가와 구분한다.','- **역사적 회귀**: OPEN1006–11, 이전 합성8. 이전 작업에서 사용했으므로 새 테스트라고 부르지 않는다.','- 원본 [PID2Graph](https://zenodo.org/records/14803338)는 기호 박스와 GraphML 연결을 제공한다. 실도면 ROI 주석에는 일반 equipment도 포함되며 위치 점수는 종류 무관이다.','- Salina·Haile PDF는 HTTP403으로 읽지 못해 사용하지 않았다. 새 프로젝트 추출 실행 전에 Virden·Ruttan으로 대체했다.','', '## 같은 기준의 결과','','| 역할·범위 | 버전 | 기호 P / R / F1 | 연결 P / R / F1 | 도면별 중앙값 평균 |','|---|---|---|---|---:|']
for name in sets:
 for v in ('v4','v5'):
  d=a[name][v];lines.append(f"| {name} | {v} | {pm(d['localization'])} | {pm(d['connections'])} | {d['mean_sheet_median_seconds']:.3f}초 |")
lines+=['','Pāhala23·24 행은 학습 진단이며 개선 일반화의 근거로 사용하지 않는다. 문턱값 검증 도면은 위 비교 그림에서 제외했다. 모든 개별 결과와 검증 도면 점수는 아래 표와 원시 JSON에 남겼다.','','![학습·검증 제외 재현율과 속도](figures/generalization-speed.png)','','## 구현과 잔여 누락','','기존 기하·형상 후보에 다중 크기 잉크 성분 및 큰 폐곡선 제안을 추가하고 학습된 객체성으로 선별한다. 기존 후보 중 낮은 점수의 배경 영역을 제거해 잘못된 영역이 선 추적을 차단하는 문제를 줄인다. 7,000개 제안·200개 최종 기호의 상한과 공간별 순회로 제목란의 빽빽한 글자가 제안 예산을 독점하지 않게 했다. 모델은 프로세스당 한 번만 로드하고 CPU 스레드는 2로 제한한다. 점수는 트리 투표 비율이며 보정된 확률이 아니다.','','옅은 회색 선과 어두운 배경에 대응하도록 배경 반전과 국소 적응 이진화를 선 마스크·접속점 판별에 적용했다. 지원 스타일의 무점 X 비접속·점 교차·T 접속 규칙은 유지한다. 일반 스타일은 여전히 미확정 교차 후보다. 기존 연결 알고리즘 이름 `port-graph-v4`/`visible-components-v4`는 유지되며 새 `symbol_detector`와 `symbol_model_sha256` 진단 필드가 검출기를 식별한다.','','![새 프로젝트 연결 누락 분류](figures/new-project-misses.png)','','누락 분류는 끝점 기호 누락→약한 원형 접점 제한→선/포트 추적 순서로 한 번만 집계한 진단이다. 독립적 인과 실험이 아니다. 정답 기호 박스를 주는 oracle 진단은 실제 종단 성능이 아니며 원시 JSON에만 별도 기록했다. 학습 검출기가 펌프·밸브를 모두 해결한 것은 아니고, 글자·해칭·복잡한 조립체의 오검출과 기호 영역 중복, 얇은 선 단절이 남는다. 자동 영향 분석의 확정 그래프로 사용하기에는 재현율이 부족해 모든 후보를 검토 필요로 유지한다.','','## 도면별 결과와 속도 비용','','| 집합 / ID / 역할 | v4 연결 P / R / F1 | v5 연결 P / R / F1 | v4→v5 중앙값 초 |','|---|---|---|---|']
for s in r['sheets']:
 b,c=s['variants']['v4'],s['variants']['v5'];lines.append(f"| {s['group']} / {s['id']} / {s['role']} | {pm(b['scores']['connections'])} | {pm(c['scores']['connections'])} | {b['timing']['median']:.3f}→{c['timing']['median']:.3f} |")
lines+=['','학습 검출기에는 추가 계산 비용이 있어 전체 지연이 단축됐다고 일괄 주장하지 않는다. 그림·표의 실제 측정값과 개별 악화 사례를 함께 판단해야 한다. 도면별 3회, 순서를 번갈아 순차 측정했고 모든 반복에서 박스·연결 쌍이 동일함을 검사했다. 입력은 최대 2400px RGB이며 OCR+기호+선+연결 추론만 측정한다. 전송·디코딩·원본 PDF 렌더링·내보내기·oracle 계산은 제외한다. 단일 호스트 결과이며 동시 작업 처리량이나 SLA가 아니다. [CSV](per-sheet.csv), [실행 결과](results/report.json)에 168회 추론의 시간과 수치를 보존했다.','','## 재현과 운영 반영','','```bash','.venv/bin/python scripts/fetch_public_benchmark.py','.venv/bin/python scripts/fetch_v3_confirmation.py','.venv/bin/python evaluation/v5/fetch_data.py','# 재학습은 backend/assets를 덮어쓰므로 별도 checkout에서 실행','.venv/bin/python evaluation/v5/train.py --variant original','# R2 실험: --variant augmented; 배포 모델로 자동 선정하지 않음','export PATH=/tmp/lineage-ocr-bookworm/bin:$PATH  # 동일 Tesseract5.3.0/eng/kor/TSV','export OMP_NUM_THREADS=1','.venv/bin/python evaluation/v5/evaluate.py --runs 3','.venv/bin/python evaluation/v5/render_report.py','```','','정확한 평가 해시는 [FROZEN](FROZEN.json), 소스 PDF·페이지 해시는 [실도면 출처](real-sources.json)와 [주석](real-labels.json), 가중치와 학습 해시는 [모델 카드](MODEL-CARD.ko.md)에 있다. 재학습 XML 직렬화는 라이브러리·병렬 실행 환경에 따라 바이트가 달라질 수 있으므로 평가에는 제공된 고정 가중치를 사용한다. 전체 회귀 테스트 35개를 통과했다. 실제 배포·외부 로그인·업로드·검토 저장·Pod 해시는 [운영 검증](../../DEPLOYED_V5_VERIFICATION.ko.md)에 기록한다.','','정부 웹사이트에 공개된 제3자 설계 문서에 별도 공개 재배포 권한을 가정하지 않는다. 원본 PDF·페이지 이미지·전체 OCR은 Git/Docker 컨텍스트에서 제외했다. 자체 생성 통계 그림과 기하 주석만 게시한다. PID2Graph 유래 가중치·파생 데이터의 출처 및 CC BY-SA4.0은 [NOTICE](../../backend/assets/NOTICE.md)를 따른다.']
existing=(HERE/'REPORT.ko.md').read_text() if (HERE/'REPORT.ko.md').exists() else '';audit='\n\n## 고정 평가 후 누락 단계 감사'+existing.split('## 고정 평가 후 누락 단계 감사',1)[1] if '## 고정 평가 후 누락 단계 감사' in existing else '';(HERE/'REPORT.ko.md').write_text('\n'.join(lines)+'\n'+audit);(HERE/'summary.json').write_text(json.dumps(a,indent=2)+'\n');print(json.dumps(a,indent=2))
